import {createHash,randomUUID} from 'node:crypto';
import type {DatabaseSync,SQLInputValue} from 'node:sqlite';
import {canonical,acceptanceServiceClaim} from '@devmesh/storage-sqlite';
import {RunnerError} from './protocol.js';
import {acceptanceServiceMigration} from './acceptance-service-migration.js';
import {acceptanceServiceReservation,acceptanceServiceProfile,acceptanceServiceActionRecord,acceptanceServiceActionRequest,acceptanceServiceNames} from './acceptance-service.js';
import type {AcceptanceServiceJournal} from './acceptance-service.js';
import type {RunnerCapacity,PreviewResourceLimits} from './preview-reservation.js';
import type {StoreInput} from './store-protocol.js';
type Row=Record<string,string|number|null>;
type Bound={controllerId:string;reservationId:string;requestHash:string};
const hash=(v:unknown)=>createHash('sha256').update(typeof v==='string'?v:canonical(v)).digest('hex');
const fail=(code:string,status=409):never=>{throw new RunnerError(code,status);};
/** Private Runner writer. Physical observations are supplied only by trusted composition. */
export function createAcceptanceServiceDomain(db:DatabaseSync,runnerId:string,fits:(limits:PreviewResourceLimits,capacity:RunnerCapacity)=>boolean){
 const get=(sql:string,...p:SQLInputValue[])=>db.prepare(sql).get(...p) as Row|undefined,all=(sql:string,...p:SQLInputValue[])=>db.prepare(sql).all(...p) as Row[],exec=(sql:string,...p:SQLInputValue[])=>db.prepare(sql).run(...p);
 const tx=<T>(body:()=>T):T=>{db.exec('BEGIN IMMEDIATE');try{const r=body();db.exec('COMMIT');return r;}catch(e){db.exec('ROLLBACK');throw e;}};
 const version=Number(Object.values(db.prepare('PRAGMA user_version').get()!)[0]);if(version===6)tx(()=>{db.exec(acceptanceServiceMigration);exec('INSERT INTO runner_schema_history VALUES(7,?,?)',hash(acceptanceServiceMigration),new Date().toISOString());if(db.prepare('PRAGMA foreign_key_check').all().length)fail('RUNNER_MIGRATION_FOREIGN_KEYS');});else if(![7,8,9,10,11,12].includes(version))fail('RUNNER_STORE_IDENTITY_MISMATCH');
 if(get('SELECT sha256 FROM runner_schema_history WHERE version=7')?.sha256!==hash(acceptanceServiceMigration)||get('SELECT version FROM runner_identity')?.version!==(version===6?7:version))fail('RUNNER_MIGRATION_DRIFT');
 const row=(i:Bound)=>{const r=get('SELECT * FROM acceptance_services WHERE controller_id=? AND reservation_id=?',i.controllerId,i.reservationId)??fail('ACCEPTANCE_SERVICE_NOT_FOUND',404);if(r.request_hash!==i.requestHash)fail('ACCEPTANCE_SERVICE_IDENTITY_CHANGED');return r;};
 const view=(r:Row)=>acceptanceServiceReservation.parse({purpose:r.purpose,reservationId:r.reservation_id,controllerId:r.controller_id,request:JSON.parse(String(r.request_json)),requestHash:r.request_hash,resourceLimits:JSON.parse(String(r.limits_json)),state:r.state,revision:r.revision,instanceId:r.instance_id,endpoint:r.endpoint_json?JSON.parse(String(r.endpoint_json)):null,fact:r.fact_json?JSON.parse(String(r.fact_json)):null,custodyState:r.custody_state,claim:r.claim_json?JSON.parse(String(r.claim_json)):null,claimHash:r.claim_hash,createdAt:r.created_at,updatedAt:r.updated_at,releasedAt:r.released_at});
 const changed=(i:Bound)=>{const r=row(i);exec('INSERT INTO acceptance_service_events VALUES(?,?,?,?)',i.reservationId,Number(r.revision),canonical(view(r)),String(r.updated_at));return view(r);};
 const profile=(id:string)=>get('SELECT * FROM acceptance_service_profiles WHERE reservation_id=?',id)??fail('ACCEPTANCE_SERVICE_PROFILE_NOT_FOUND',404);
 const journal=(p:Row):AcceptanceServiceJournal=>({profile:acceptanceServiceProfile.parse(JSON.parse(String(p.profile_json))),profileHash:String(p.profile_hash),networkId:p.network_id as string|null,containerId:p.container_id as string|null,actions:all('SELECT * FROM acceptance_service_actions WHERE reservation_id=? ORDER BY created_at,kind',String(p.reservation_id)).map(a=>acceptanceServiceActionRecord.parse({request:JSON.parse(String(a.request_json)),requestHash:a.request_hash,state:a.state,observation:a.observation_json?JSON.parse(String(a.observation_json)):null,createdAt:a.created_at,observedAt:a.observed_at}))});
 const aborting=(r:Row)=>!!get('SELECT 1 FROM acceptance_service_aborts WHERE operation_id=?',r.operation_id!);
 const publishing=(r:Row)=>!!get('SELECT 1 FROM release_retirements WHERE reservation_id=?',r.reservation_id!);
 const mutable=(r:Row)=>{if(publishing(r))fail('RELEASE_RETIREMENT_ENROLLED');if(aborting(r))fail('ACCEPTANCE_ABORT_REQUESTED');if(r.released_at!==null||r.custody_state!=='PREPARING')fail('ACCEPTANCE_SERVICE_EXECUTION_CLOSED');};
 return {
  acceptanceServiceReserve(i:StoreInput<'acceptanceServiceReserve'>){return tx(()=>{
   const r=i.request.preparation;if(r.runnerId!==runnerId||i.requestHash!==hash(i.request))fail('ACCEPTANCE_SERVICE_IDENTITY_CHANGED');
   const old=get('SELECT * FROM acceptance_services WHERE controller_id=? AND operation_id=?',i.controllerId,r.operationId);if(old){if(old.request_hash!==i.requestHash||old.limits_json!==canonical(i.resourceLimits))fail('IDEMPOTENCY_KEY_REUSED');return view(old);}
   if(get('SELECT 1 FROM acceptance_services WHERE released_at IS NULL AND (dataset_id=? OR release_id=?)',r.target.datasetId,r.releaseId)||get('SELECT 1 FROM preview_reservations WHERE released_at IS NULL AND dataset_id=?',r.target.datasetId))fail('ACCEPTANCE_SERVICE_BUSY');
   if(get('SELECT 1 FROM release_retirements WHERE dataset_id=?',r.target.datasetId))fail('ACCEPTANCE_SERVICE_BUSY');
   if(!fits(i.resourceLimits,i.capacity))fail('RUNNER_CAPACITY_EXHAUSTED',429);
   const id='acceptance_'+randomUUID().replaceAll('-',''),at=new Date().toISOString();exec("INSERT INTO acceptance_services(reservation_id,controller_id,operation_id,release_id,dataset_id,purpose,request_hash,request_json,limits_json,state,revision,custody_state,created_at,updated_at) VALUES(?,?,?,?,?,'ACCEPTANCE',?,?,?,'RESERVED',0,'PREPARING',?,?)",id,i.controllerId,r.operationId,r.releaseId,r.target.datasetId,i.requestHash,canonical(i.request),canonical(i.resourceLimits),at,at);return changed({controllerId:i.controllerId,reservationId:id,requestHash:i.requestHash});
  });},
  acceptanceServiceGet(i:StoreInput<'acceptanceServiceGet'>){return view(row(i));},
  acceptanceServiceByOperation(i:StoreInput<'acceptanceServiceByOperation'>){const r=get('SELECT * FROM acceptance_services WHERE controller_id=? AND operation_id=?',i.controllerId,i.operationId);return r?view(r):null;},
  acceptanceServicePage(i:StoreInput<'acceptanceServicePage'>){const rows=all('SELECT * FROM acceptance_services WHERE controller_id=? AND sequence>? AND released_at IS NULL ORDER BY sequence LIMIT ?',i.controllerId,i.afterSequence??0,(i.limit??20)+1),page=rows.slice(0,i.limit??20);return {items:page.map(r=>({sequence:Number(r.sequence),reservation:view(r)})),nextSequence:rows.length>page.length?Number(page.at(-1)!.sequence):null};},
  acceptanceServiceDispatch(i:StoreInput<'acceptanceServiceDispatch'>){return tx(()=>{const r=row(i);if(r.state!=='RESERVED')return {dispatch:false,reservation:view(r)};if(aborting(r))fail('ACCEPTANCE_ABORT_REQUESTED');profile(i.reservationId);const at=new Date().toISOString();exec("UPDATE acceptance_services SET state='DISPATCHED',revision=revision+1,updated_at=? WHERE reservation_id=?",at,i.reservationId);return {dispatch:true,reservation:changed(i)};});},
  acceptanceServiceCancel(i:StoreInput<'acceptanceServiceCancel'>){return tx(()=>{const r=row(i);if(r.state==='CANCELLED')return view(r);if(r.state!=='RESERVED')fail('ACCEPTANCE_SERVICE_ALREADY_DISPATCHED');const at=new Date().toISOString();exec("UPDATE acceptance_services SET state='CANCELLED',revision=revision+1,updated_at=?,released_at=? WHERE reservation_id=?",at,at,i.reservationId);return changed(i);});},
  acceptanceServiceRecord(i:StoreInput<'acceptanceServiceRecord'>){return tx(()=>{
   const r=row(i),request=JSON.parse(String(r.request_json)).preparation,f=i.fact;if(f.operationId!==request.operationId||f.releaseId!==request.releaseId||f.datasetId!==request.target.datasetId||f.imageDigest!==request.image.imageDigest)fail('ACCEPTANCE_SERVICE_IDENTITY_CHANGED');if(r.fact_json===canonical(f))return view(r);if(publishing(r))fail('RELEASE_RETIREMENT_ENROLLED');if(aborting(r))fail('ACCEPTANCE_ABORT_REQUESTED');if(i.expectedRevision!==r.revision)fail('ACCEPTANCE_SERVICE_REVISION_CHANGED');if(['RESERVED','CANCELLED','EXITED'].includes(String(r.state)))fail('ACCEPTANCE_SERVICE_NOT_OBSERVABLE');
   const p=profile(i.reservationId),previous=r.fact_json?JSON.parse(String(r.fact_json)):null,at=Date.parse(f.checkedAt);if(at>Date.now()||at<Date.parse(String(r.created_at))||previous&&at<Date.parse(previous.checkedAt))fail('ACCEPTANCE_SERVICE_OBSERVATION_STALE');
   if(f.instanceId!==null&&f.instanceId!==p.container_id||r.instance_id!==null&&f.instanceId!==null&&f.instanceId!==r.instance_id||r.endpoint_json!==null&&f.endpoint!==null&&canonical(f.endpoint)!==r.endpoint_json)fail('ACCEPTANCE_SERVICE_IDENTITY_CHANGED');
   if(f.state==='HEALTHY'&&!get("SELECT 1 FROM acceptance_service_actions WHERE reservation_id=? AND kind='START' AND state='OBSERVED' AND json_extract(observation_json,'$.state')='RUNNING'",i.reservationId))fail('ACCEPTANCE_SERVICE_START_UNVERIFIED');
   const state=f.state==='EXITED'?'EXITED':f.state==='UNKNOWN'?'UNKNOWN':f.state==='CREATED'?'DISPATCHED':'ACTIVE',now=new Date().toISOString();exec('UPDATE acceptance_services SET state=?,revision=revision+1,instance_id=coalesce(instance_id,?),endpoint_json=coalesce(endpoint_json,?),fact_json=?,updated_at=?,released_at=? WHERE reservation_id=?',state,f.instanceId,f.endpoint?canonical(f.endpoint):null,canonical(f),now,state==='EXITED'?now:null,i.reservationId);return changed(i);
  });},
  acceptanceServiceProfilePrepare(i:StoreInput<'acceptanceServiceProfilePrepare'>){return tx(()=>{const r=row(i),p=i.profile,names=acceptanceServiceNames(i.reservationId),old=get('SELECT * FROM acceptance_service_profiles WHERE reservation_id=?',i.reservationId);if(p.reservationId!==i.reservationId||p.requestHash!==i.requestHash||canonical(p.resourceLimits)!==r.limits_json||p.networkName!==names.networkName||p.containerName!==names.containerName)fail('ACCEPTANCE_SERVICE_PROFILE_CHANGED');if(old){if(old.profile_json!==canonical(p))fail('ACCEPTANCE_SERVICE_PROFILE_CHANGED');return journal(old);}if(r.state!=='RESERVED')fail('ACCEPTANCE_SERVICE_ALREADY_DISPATCHED');exec('INSERT INTO acceptance_service_profiles VALUES(?,?,?,?,NULL,NULL,?)',i.reservationId,i.requestHash,hash(p),canonical(p),new Date().toISOString());return journal(profile(i.reservationId));});},
  acceptanceServiceJournal(i:StoreInput<'acceptanceServiceJournal'>){row(i);const p=get('SELECT * FROM acceptance_service_profiles WHERE reservation_id=?',i.reservationId);return p?journal(p):null;},
  acceptanceServiceActionBegin(i:StoreInput<'acceptanceServiceActionBegin'>){return tx(()=>{
   const r=row(i),p=profile(i.reservationId),old=get('SELECT * FROM acceptance_service_actions WHERE reservation_id=? AND kind=?',i.reservationId,i.kind);if(old)return {dispatch:false,journal:journal(p)};mutable(r);if(r.state==='RESERVED')fail('ACCEPTANCE_SERVICE_NOT_DISPATCHED');
   if(i.kind!=='NETWORK_CREATE'&&!p.network_id||i.kind==='START'&&!p.container_id)fail('ACCEPTANCE_SERVICE_PREDECESSOR_UNKNOWN');
   const request=acceptanceServiceActionRequest.parse({schemaVersion:'devmesh.acceptance-service-action.v1',purpose:'ACCEPTANCE',operationId:'op_'+hash('acceptance-service:'+i.reservationId+':'+i.kind).slice(0,32),reservationId:i.reservationId,serviceRequestHash:i.requestHash,profileHash:p.profile_hash,kind:i.kind,networkId:p.network_id,containerId:p.container_id});exec("INSERT INTO acceptance_service_actions VALUES(?,?,?,?,?,'SENT',NULL,?,NULL)",i.reservationId,i.kind,String(p.profile_hash),hash(request),canonical(request),new Date().toISOString());return {dispatch:true,journal:journal(p)};
  });},
  acceptanceServiceActionAuthorized(i:StoreInput<'acceptanceServiceActionAuthorized'>){const r=row(i),a=get('SELECT * FROM acceptance_service_actions WHERE reservation_id=? AND kind=?',i.reservationId,i.kind);return {allowed:!publishing(r)&&!aborting(r)&&r.released_at===null&&r.custody_state==='PREPARING'&&r.state!=='RESERVED'&&a?.state==='SENT'&&a.request_hash===i.actionRequestHash};},
  acceptanceServiceActionObserve(i:StoreInput<'acceptanceServiceActionObserve'>){return tx(()=>{
   row(i);const p=profile(i.reservationId),a=get('SELECT * FROM acceptance_service_actions WHERE reservation_id=? AND kind=?',i.reservationId,i.kind)??fail('ACCEPTANCE_SERVICE_ACTION_NOT_FOUND',404),o=i.observation;if(a.request_hash!==i.actionRequestHash)fail('ACCEPTANCE_SERVICE_IDENTITY_CHANGED');if(a.state==='OBSERVED'){if(a.observation_json!==canonical(o))fail('ACCEPTANCE_SERVICE_ACTION_IMMUTABLE');return journal(p);}
   if(Date.parse(o.checkedAt)<Date.parse(String(a.created_at))||Date.parse(o.checkedAt)>Date.now())fail('ACCEPTANCE_SERVICE_OBSERVATION_STALE');if(i.kind==='NETWORK_CREATE'&&o.state!=='CREATED'||i.kind==='CREATE'&&o.state!=='CREATED'||i.kind==='START'&&o.state==='CREATED')fail('ACCEPTANCE_SERVICE_ACTION_UNVERIFIED');
   const key=i.kind==='NETWORK_CREATE'?'network_id':'container_id';if(p[key]!==null&&p[key]!==o.objectId||i.kind==='START'&&p.container_id!==o.objectId)fail('ACCEPTANCE_SERVICE_IDENTITY_CHANGED');if(i.kind!=='START')exec('UPDATE acceptance_service_profiles SET '+key+'=coalesce('+key+',?) WHERE reservation_id=?',o.objectId,i.reservationId);exec("UPDATE acceptance_service_actions SET state='OBSERVED',observation_json=?,observed_at=? WHERE reservation_id=? AND kind=?",canonical(o),new Date().toISOString(),i.reservationId,i.kind);return journal(profile(i.reservationId));
  });},
  acceptanceServiceHold(i:StoreInput<'acceptanceServiceHold'>){return tx(()=>{
   const r=row(i),v=view(r),p=profile(i.reservationId),q=v.request.preparation,f=v.fact,claim=acceptanceServiceClaim.parse(i.claim);if(i.claimHash!==hash(claim)||claim.acceptanceRequestHash!==v.request.acceptanceRequestHash||claim.serviceRequestHash!==i.requestHash||claim.reservationId!==i.reservationId||claim.profileHash!==p.profile_hash||claim.instanceId!==r.instance_id)fail('ACCEPTANCE_SERVICE_CLAIM_CHANGED');for(const k of ['operationId','releaseId','projectId','runId','candidateId','manifestHash','reviewHash','dataPlanHash'] as const)if(claim[k]!==q[k])fail('ACCEPTANCE_SERVICE_CLAIM_CHANGED');if(claim.datasetId!==q.target.datasetId||claim.imageDigest!==q.image.imageDigest)fail('ACCEPTANCE_SERVICE_CLAIM_CHANGED');if(r.claim_hash!==null){if(r.claim_hash!==i.claimHash||r.claim_json!==canonical(claim))fail('ACCEPTANCE_SERVICE_CLAIM_CHANGED');return v;}
   const age=f?Date.now()-Date.parse(f.checkedAt):-1;if(aborting(r))fail('ACCEPTANCE_ABORT_REQUESTED');if(r.released_at!==null||f?.state!=='HEALTHY'||f.instanceId!==claim.instanceId||!f.endpoint||age<0||age>30000)fail('ACCEPTANCE_SERVICE_HOLD_UNAVAILABLE');const at=new Date().toISOString();exec("UPDATE acceptance_services SET custody_state='RELEASE_HELD',claim_json=?,claim_hash=?,revision=revision+1,updated_at=? WHERE reservation_id=?",canonical(claim),i.claimHash,at,i.reservationId);return changed(i);
  });},
 };
}
