import {createHash} from 'node:crypto';
import type {DatabaseSync,SQLInputValue} from 'node:sqlite';
import {canonical} from '@devmesh/storage-sqlite';
import {RunnerError} from './protocol.js';
import {cleanupMigration} from './cleanup-migration.js';
import {previewCleanupAction,previewCleanupRequest} from './preview-cleanup.js';
import type {StoreInput} from './store-protocol.js';
type Row=Record<string,string|number|null>;
type Bound={controllerId:string;reservationId:string;requestHash:string};
const hash=(v:unknown)=>createHash('sha256').update(typeof v==='string'?v:canonical(v)).digest('hex');
const fail=(code:string,status=409):never=>{throw new RunnerError(code,status);};
export function createPreviewCleanupDomain(db:DatabaseSync,removed:(i:Bound,checkedAt:string)=>void){
 const get=(sql:string,...p:SQLInputValue[])=>db.prepare(sql).get(...p) as Row|undefined,all=(sql:string,...p:SQLInputValue[])=>db.prepare(sql).all(...p) as Row[],exec=(sql:string,...p:SQLInputValue[])=>db.prepare(sql).run(...p);
 const tx=<T>(body:()=>T):T=>{db.exec('BEGIN IMMEDIATE');try{const r=body();db.exec('COMMIT');return r;}catch(e){db.exec('ROLLBACK');throw e;}};
 const version=Number(Object.values(db.prepare('PRAGMA user_version').get()!)[0]);
  if(version===5){db.exec('PRAGMA foreign_keys=OFF');try{if(Number(Object.values(db.prepare('PRAGMA foreign_keys').get()!)[0])!==0)fail('RUNNER_MIGRATION_FAILED');tx(()=>{db.exec(cleanupMigration);exec('INSERT INTO runner_schema_history VALUES(6,?,?)',hash(cleanupMigration),new Date().toISOString());if(db.prepare('PRAGMA foreign_key_check').all().length)fail('RUNNER_MIGRATION_FOREIGN_KEYS');});}finally{db.exec('PRAGMA foreign_keys=ON');}}else if(![6,7,8,9,10,11,12].includes(version))fail('RUNNER_STORE_IDENTITY_MISMATCH');
  if(get('SELECT sha256 FROM runner_schema_history WHERE version=6')?.sha256!==hash(cleanupMigration)||get('SELECT version FROM runner_identity')?.version!==(version===5?6:version))fail('RUNNER_MIGRATION_DRIFT');
 if(Number(Object.values(db.prepare('PRAGMA foreign_keys').get()!)[0])!==1)fail('RUNNER_MIGRATION_FOREIGN_KEYS');
 const reservation=(i:Bound)=>{const r=get('SELECT * FROM preview_reservations WHERE controller_id=? AND reservation_id=?',i.controllerId,i.reservationId)??fail('PREVIEW_RESERVATION_NOT_FOUND',404);if(r.request_hash!==i.requestHash)fail('PREVIEW_RESERVATION_IDENTITY_MISMATCH');return r;};
 const action=(id:string,kind:string)=>get('SELECT * FROM preview_cleanup_actions WHERE reservation_id=? AND kind=?',id,kind);
 const view=(r:Row)=>previewCleanupAction.parse({request:JSON.parse(String(r.request_json)),requestHash:r.request_hash,state:r.state,observation:r.observation_json?JSON.parse(String(r.observation_json)):null,createdAt:r.created_at,observedAt:r.observed_at});
 const eligible=(i:Bound)=>{const r=reservation(i),life=get('SELECT state FROM preview_lifecycles WHERE reservation_id=?',i.reservationId);if(life?.state!=='STOPPING')fail('PREVIEW_CLEANUP_CUSTODY_REQUIRED');const p=get('SELECT * FROM preview_container_profiles WHERE reservation_id=?',i.reservationId)??fail('PREVIEW_CLEANUP_ORIGINAL_UNKNOWN'),stop=get("SELECT request_hash FROM preview_container_actions WHERE reservation_id=? AND kind='STOP'",i.reservationId)??fail('PREVIEW_CLEANUP_ORIGINAL_UNKNOWN');if(!p.container_id||!p.network_id||r.instance_id!==p.container_id)fail('PREVIEW_CLEANUP_ORIGINAL_UNKNOWN');return {r,p,stop};};
 return {
  previewCleanupGet(i:StoreInput<'previewCleanupGet'>){reservation(i);return all('SELECT * FROM preview_cleanup_actions WHERE reservation_id=? ORDER BY created_at,kind',i.reservationId).map(view);},
  previewCleanupPage(i:StoreInput<'previewCleanupPage'>){const rows=all("SELECT r.sequence,r.reservation_id,r.request_hash FROM preview_reservations r JOIN preview_lifecycles l USING(reservation_id) JOIN preview_container_profiles p USING(reservation_id) WHERE r.controller_id=? AND r.sequence>? AND l.state='STOPPING' AND p.container_id IS NOT NULL AND p.container_id=r.instance_id AND p.network_id IS NOT NULL AND EXISTS(SELECT 1 FROM preview_container_actions a WHERE a.reservation_id=r.reservation_id AND a.kind='STOP') AND NOT EXISTS(SELECT 1 FROM preview_cleanup_actions c WHERE c.reservation_id=r.reservation_id AND c.kind='NETWORK_REMOVE' AND c.state='OBSERVED') ORDER BY r.sequence LIMIT ?",i.controllerId,i.afterSequence??0,(i.limit??20)+1),more=rows.length>(i.limit??20);if(more)rows.pop();return {items:rows.map(r=>({sequence:Number(r.sequence),reservationId:String(r.reservation_id),requestHash:String(r.request_hash)})),nextSequence:more?Number(rows.at(-1)!.sequence):null};},
  previewCleanupActionBegin(i:StoreInput<'previewCleanupActionBegin'>){return tx(()=>{const {p,stop}=eligible(i),old=action(i.reservationId,i.kind);if(old)return {dispatch:false,action:view(old)};if(i.kind==='NETWORK_REMOVE'&&action(i.reservationId,'CONTAINER_REMOVE')?.state!=='OBSERVED')fail('PREVIEW_CLEANUP_PREDECESSOR_UNKNOWN');const request=previewCleanupRequest.parse({schemaVersion:'devmesh.preview-cleanup.v1',operationId:'op_'+hash('runner-preview-cleanup:'+i.reservationId+':'+i.kind).slice(0,32),reservationId:i.reservationId,startRequestHash:i.requestHash,profileHash:p.profile_hash,stopRequestHash:stop.request_hash,containerId:p.container_id,networkId:p.network_id,kind:i.kind});exec("INSERT INTO preview_cleanup_actions VALUES(?,?,?,?,?,'SENT',NULL,?,NULL)",i.reservationId,i.kind,String(p.profile_hash),hash(request),canonical(request),new Date().toISOString());return {dispatch:true,action:view(action(i.reservationId,i.kind)!)};});},
  previewCleanupActionAuthorized(i:StoreInput<'previewCleanupActionAuthorized'>){reservation(i);const a=action(i.reservationId,i.kind);try{eligible(i);return {allowed:a?.state==='SENT'&&a.request_hash===i.actionRequestHash&&(i.kind!=='NETWORK_REMOVE'||action(i.reservationId,'CONTAINER_REMOVE')?.state==='OBSERVED')};}catch(error){if(error instanceof RunnerError)return {allowed:false};throw error;}},
  previewCleanupActionObserve(i:StoreInput<'previewCleanupActionObserve'>){return tx(()=>{const {p}=eligible(i),a=action(i.reservationId,i.kind)??fail('PREVIEW_CLEANUP_ACTION_NOT_FOUND',404),o=i.observation;if(a.request_hash!==i.actionRequestHash||o.objectId!==(i.kind==='CONTAINER_REMOVE'?p.container_id:p.network_id))fail('PREVIEW_CLEANUP_IDENTITY_CHANGED');if(a.state==='OBSERVED'){if(a.observation_json!==canonical(o))fail('PREVIEW_CLEANUP_IMMUTABLE');return view(a);}if(Date.parse(o.checkedAt)<Date.parse(String(a.created_at))||Date.parse(o.checkedAt)>Date.now())fail('PREVIEW_CLEANUP_OBSERVATION_STALE');if(i.kind==='NETWORK_REMOVE'&&action(i.reservationId,'CONTAINER_REMOVE')?.state!=='OBSERVED')fail('PREVIEW_CLEANUP_PREDECESSOR_UNKNOWN');exec("UPDATE preview_cleanup_actions SET state='OBSERVED',observation_json=?,observed_at=? WHERE reservation_id=? AND kind=?",canonical(o),new Date().toISOString(),i.reservationId,i.kind);if(i.kind==='CONTAINER_REMOVE')removed(i,o.checkedAt);return view(action(i.reservationId,i.kind)!);});},
 };
}
